<template><div class="page-container fsr-page"><div class="page-head"><div><h2>变化图斑库</h2><p>统一管理变化图斑、风险判定与处置计划。</p></div><el-button type="primary" @click="load">刷新图斑</el-button></div><div class="panel"><div class="panel-title">变化图斑列表</div><el-form inline><el-form-item label="状态"><el-select v-model="filters.status" clearable style="width:130px"><el-option v-for="i in statusOptions" :key="i.value" v-bind="i"/></el-select></el-form-item><el-form-item label="问题类型"><el-select v-model="filters.type" clearable style="width:130px"><el-option v-for="i in typeOptions" :key="i.value" v-bind="i"/></el-select></el-form-item><el-form-item label="来源"><el-select v-model="filters.source" clearable style="width:130px"><el-option v-for="i in sourceOptions" :key="i.value" v-bind="i"/></el-select></el-form-item></el-form><el-table :data="rows" stripe border><el-table-column type="index" label="序号" width="55"/><el-table-column prop="code" label="图斑编号" width="150"/><el-table-column prop="foundTime" label="记录时间" width="110"/><el-table-column prop="regionName" label="所在位置" min-width="145"/><el-table-column label="疑似问题类型" width="120"><template #default="{row}">{{ typeName(row.type) }}</template></el-table-column><el-table-column label="图斑面积" width="95"><template #default="{row}">{{ row.spot?.areaMu || 0 }}亩</template></el-table-column><el-table-column label="风险等级" width="105"><template #default="{row}"><el-tag :type="riskType(row.riskFinal)">{{ riskName(row.riskFinal) }}</el-tag></template></el-table-column><el-table-column label="风险判定依据" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.riskBasis }}</template></el-table-column><el-table-column label="关联地块" width="130"><template #default="{row}">{{ row.spot?.plotId || '待关联' }}</template></el-table-column><el-table-column prop="subjectName" label="关联主体" min-width="150"/><el-table-column label="计划落实" min-width="150"><template #default="{row}">{{ row.dispatchRequirement || '待制定' }}</template></el-table-column><el-table-column label="图斑状态" width="105"><template #default="{row}"><el-tag size="small">{{ statusName(row.status) }}</el-tag></template></el-table-column><el-table-column label="数据来源" width="115"><template #default="{row}">{{ sourceName(row.source) }}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">详情</el-button><el-button v-if="row.status==='pending'" link type="success" @click="dispatch(row)">派发</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="变化图斑详情" width="900px"><template v-if="current"><el-descriptions :column="3" border><el-descriptions-item label="图斑编号">{{ current.code }}</el-descriptions-item><el-descriptions-item label="记录时间">{{ current.foundTime }}</el-descriptions-item><el-descriptions-item label="问题类型">{{ typeName(current.type) }}</el-descriptions-item><el-descriptions-item label="所在位置">{{ current.regionName }}</el-descriptions-item><el-descriptions-item label="变化前面积">{{ current.spot?.beforeAreaMu || current.spot?.areaMu || 0 }}亩</el-descriptions-item><el-descriptions-item label="变化后面积">{{ current.spot?.afterAreaMu || current.spot?.areaMu || 0 }}亩</el-descriptions-item><el-descriptions-item label="变化率">{{ current.spot?.changeRate || '—' }}</el-descriptions-item><el-descriptions-item label="中心经纬度">{{ current.spot?.center?.join?.(', ') || '待采集' }}</el-descriptions-item><el-descriptions-item label="风险自动等级">{{ riskName(current.riskAuto) }}</el-descriptions-item><el-descriptions-item label="风险最终等级">{{ riskName(current.riskFinal) }}</el-descriptions-item><el-descriptions-item label="风险判定依据" :span="3">{{ current.riskBasis }}{{ current.riskAdjustReason ? `；人工调整：${current.riskAdjustReason}` : '' }}</el-descriptions-item><el-descriptions-item label="关联主体">{{ current.subjectName }}</el-descriptions-item><el-descriptions-item label="数据来源">{{ sourceName(current.source) }}</el-descriptions-item><el-descriptions-item label="问题描述" :span="3">{{ current.desc }}</el-descriptions-item></el-descriptions></template></el-dialog><el-dialog v-model="dispatchVisible" title="派发核查任务" width="520px"><el-form label-width="90px"><el-form-item label="核查责任人"><el-input v-model="dispatchForm.assignee"/></el-form-item><el-form-item label="核查时限"><el-input-number v-model="dispatchForm.deadlineDays" :min="1" :max="60"/></el-form-item><el-form-item label="计划落实"><el-input v-model="dispatchForm.requirement" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dispatchVisible=false">取消</el-button><el-button type="primary" @click="submitDispatch">确认派发</el-button></template></el-dialog></div></template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { fetchEvents,dispatchTask } from '@/api/fsr';import { useUserStore } from '@/stores/user'
const userStore=useUserStore();const allRows=ref([]);const visible=ref(false);const dispatchVisible=ref(false);const current=ref(null);const filters=reactive({status:'',type:'',source:''});const dispatchForm=reactive({assignee:'',deadlineDays:7,requirement:''});const statusOptions=[{label:'待派发',value:'pending'},{label:'待核查',value:'checking'},{label:'待审核',value:'reviewing'},{label:'整改中',value:'rectifying'},{label:'待复核',value:'recheck'},{label:'已结案',value:'closed'}];const typeOptions=[{label:'毁麦毁粮',value:'baomai'},{label:'撂荒',value:'piaohuang'},{label:'非粮化',value:'feilianghua'},{label:'长势异常',value:'zhangshi'}];const sourceOptions=[{label:'遥感卫片',value:'remote'},{label:'无人机航拍',value:'fence'},{label:'市级反馈',value:'platform'},{label:'县级反馈',value:'grid'},{label:'苗情监测报告',value:'snapshot'}];const map={pending:'待派发',checking:'待核查',reviewing:'待审核',rectifying:'整改中',recheck:'待复核',closed:'已结案',baomai:'毁麦毁粮',piaohuang:'撂荒',feilianghua:'非粮化',zhangshi:'长势异常',remote:'遥感卫片',fence:'无人机航拍',platform:'市级反馈',grid:'县级反馈',snapshot:'苗情监测报告',low:'低风险',medium:'中风险',high:'高风险'};const statusName=x=>map[x]||'未知状态';const typeName=x=>map[x]||'其他问题';const sourceName=x=>map[x]||'其他来源';const riskName=x=>map[x]||'未知';const riskType=x=>({high:'danger',medium:'warning',low:'success'}[x]||'info');const assess=e=>{const area=Number(e.spot?.areaMu||0);const basic=e.desc?.includes('永久基本农田')||e.type==='feilianghua'||e.regionName?.includes('重点')||e.regionName?.includes('基本农田');const risk=basic||area>=400||e.type==='baomai'?'high':area>=200||e.type==='zhangshi'?'medium':'low';return {risk,basis:`图斑面积${area}亩；${basic?'涉及永久基本农田或重点问题；':'未识别永久基本农田；'}问题类型为${typeName(e.type)}`}};const rows=computed(()=>allRows.value.filter(e=>(!filters.status||e.status===filters.status)&&(!filters.type||e.type===filters.type)&&(!filters.source||e.source===filters.source)).map(e=>{const a=assess(e);return {...e,riskAuto:e.riskAuto||a.risk,riskFinal:e.riskFinal||e.risk||a.risk,riskBasis:e.riskBasis||a.basis}}));const load=async()=>{allRows.value=await fetchEvents(userStore.role,{})};const open=r=>{current.value=r;visible.value=true};const dispatch=r=>{current.value=r;dispatchForm.assignee=r.assignee||'';dispatchVisible.value=true};const submitDispatch=async()=>{if(!dispatchForm.assignee.trim())return ElMessage.warning('请填写核查责任人');const r=await dispatchTask(current.value.id,dispatchForm);if(!r.success)return ElMessage.error(r.message||'派发失败');ElMessage.success('任务已派发');dispatchVisible.value=false;visible.value=false;load()};onMounted(load)
</script><style scoped lang="scss">.fsr-page{overflow:auto}.page-head{display:flex;justify-content:space-between;margin-bottom:14px}.page-head h2{margin:4px 0;font-size:22px}.page-head p{margin:0;color:var(--ah-text-secondary);font-size:13px}.panel-title{margin-bottom:12px;font-weight:700}</style>